export function ServiceMap() {
  const [active, setActive] = useState<string | null>(null);

  return (
    <section id="network" className="relative py-32 overflow-hidden bg-[#0a0a0c]">
      {/* Cinematic Lighting & Grid */}
      <div className="absolute inset-0 -z-10 bg-[linear-gradient(to_right,#80808012_1px,transparent_1px),linear-gradient(to_bottom,#80808012_1px,transparent_1px)] bg-[size:40px_40px]" />
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-3/4 h-1/2 bg-primary/10 blur-[120px] rounded-full pointer-events-none" />

      <div className="mx-auto max-w-7xl px-4 sm:px-6 relative z-10">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
          className="text-center max-w-3xl mx-auto mb-16"
        >
          <div className="inline-flex items-center gap-2 rounded-sm border border-primary/30 bg-primary/5 px-3 py-1.5 text-xs font-mono text-primary mb-6 shadow-[0_0_15px_rgba(255,193,7,0.15)] uppercase tracking-widest">
            <Activity className="h-3 w-3 animate-pulse" />
            Infrastructure Status: Operational
          </div>
          
          <h2 className="text-4xl md:text-5xl lg:text-6xl font-bold mb-6 text-white tracking-tight">
            Nationwide <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary to-yellow-200 drop-shadow-[0_0_15px_rgba(255,193,7,0.5)]">Service Network</span>
          </h2>
          <p className="text-lg text-white/60 leading-relaxed max-w-2xl mx-auto">
            Our AI-driven mobility OS tracks certified garage hubs in real-time. 
            Experience unprecedented response times, transparent diagnostics, and 
            seamless service across the entire country.
          </p>
        </motion.div>

        {/* Futuristic Dashboard Container */}
        <motion.div
          initial={{ opacity: 0, scale: 0.98 }}
          whileInView={{ opacity: 1, scale: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.9 }}
          className="relative max-w-6xl mx-auto bg-[#0d0e12]/80 backdrop-blur-xl rounded-2xl sm:rounded-[2rem] p-2 sm:p-6 shadow-[0_30px_100px_-20px_rgba(0,0,0,1)] border border-white/5 overflow-hidden"
        >

          <div className="relative w-full aspect-square md:aspect-[16/10] bg-gradient-to-br from-[#0f1016] via-[#0a0b0f] to-[#050506] rounded-2xl overflow-hidden shadow-[inset_0_0_120px_rgba(0,0,0,0.8),0_20px_40px_-10px_rgba(0,0,0,0.5)] border border-white/10 flex items-center justify-center ring-1 ring-white/5">
            {/* Holographic grid overlay */}
            <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iNDAiIGhlaWdodD0iNDAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PGcgc3Ryb2tlPSJyZ2JhKDI1NSwyNTUsMjU1LDAuMDMpIiBzdHJva2Utd2lkdGg9IjEiIGZpbGw9Im5vbmUiPjxwb2x5Z29uIHBvaW50cz0iMCwwIDQwLDAgNDAsNDAgMCw0MCIvPjwvZz48L3N2Zz4=')] opacity-50 z-0 mix-blend-overlay pointer-events-none" />
            
            {/* Scanning line animation */}
            <motion.div 
              className="absolute inset-0 z-10 bg-gradient-to-b from-transparent via-primary/5 to-transparent h-[10%] w-full pointer-events-none"
              animate={{
                top: ["-10%", "110%"],
              }}
              transition={{
                duration: 8,
                repeat: Infinity,
                ease: "linear",
              }}
            />

            {/* Inner square container to perfectly align HTML overlay coordinates with SVG viewBox */}
            <div className="relative h-full aspect-square flex-shrink-0 z-20">
              <svg
                viewBox="0 0 100 100"
                className="absolute inset-0 w-full h-full z-10"
                preserveAspectRatio="xMidYMid meet"
              >
                <defs>
                  <filter id="neonGlow" x="-20%" y="-20%" width="140%" height="140%">
                    <feGaussianBlur stdDeviation="1.5" result="blur" />
                    <feMerge>
                      <feMergeNode in="blur" />
                      <feMergeNode in="SourceGraphic" />
                    </feMerge>
                  </filter>
                  <linearGradient id="routeGradient" x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0%" stopColor="oklch(0.85 0.18 90)" stopOpacity="1" />
                    <stop offset="100%" stopColor="oklch(0.85 0.18 90)" stopOpacity="0.1" />
                  </linearGradient>
                </defs>

                {/* Map Outline */}
                <motion.path
                  d={BD_PATH}
                  fill="#111216"
                  stroke="oklch(0.85 0.18 90 / 0.4)"
                  strokeWidth="0.15"
                  strokeLinejoin="round"
                  filter="url(#neonGlow)"
                  initial={{ pathLength: 0, opacity: 0 }}
                  whileInView={{ pathLength: 1, opacity: 1 }}
                  viewport={{ once: true }}
                  transition={{ duration: 3, ease: "easeInOut" }}
                />

                {/* Network Connections */}
                {connections.map(([c1, c2], i) => {
                  const p1 = centers.find((c) => c.id === c1)!;
                  const p2 = centers.find((c) => c.id === c2)!;
                  // Add a subtle curve to the line
                  const cx = (p1.x + p2.x) / 2 + (p1.y > p2.y ? 8 : -8);
                  const cy = (p1.y + p2.y) / 2 - 2;
                  const path = `M${p1.x},${p1.y} Q${cx},${cy} ${p2.x},${p2.y}`;

                  return (
                    <g key={`conn-${c1}-${c2}`}>
                      <motion.path
                        d={path}
                        fill="none"
                        stroke="url(#routeGradient)"
                        strokeWidth="0.15"
                        initial={{ pathLength: 0 }}
                        whileInView={{ pathLength: 1 }}
                        viewport={{ once: true }}
                        transition={{ duration: 2, delay: 1 + i * 0.15 }}
                      />
                      {/* Data Flow animation along path */}
                      <motion.circle r="0.4" fill="oklch(0.85 0.18 90)" filter="url(#neonGlow)">
                        <animateMotion
                          dur="4s"
                          repeatCount="indefinite"
                          path={path}
                          begin={`${i * 0.5}s`}
                        />
                      </motion.circle>
                    </g>
                  );
                })}
              </svg>

              {/* City Nodes */}
              <div className="absolute inset-0 z-20">
                {centers.map((c) => {
                  const isActive = c.id === active;
                  const isHQ = c.id === "dhk";
                  return (
                    <div
                      key={c.id}
                      className={`absolute ${isActive ? "z-50" : "z-10"}`}
                      style={{
                        left: `${c.x}%`,
                        top: `${c.y}%`,
                        transform: "translate(-50%, -50%)",
                      }}
                      onMouseEnter={() => setActive(c.id)}
                      onMouseLeave={() => setActive(null)}
                      onClick={() => setActive(c.id)}
                    >
                      {/* Node Visual */}
                      <div className="relative group cursor-pointer flex items-center justify-center">
                        {isHQ ? (
                          // Premium HQ Design
                          <>
                            {/* Massive Pulsing Aura */}
                            <div className="absolute inset-0 rounded-full blur-[25px] transition-all duration-700 bg-primary/30 scale-[12] animate-pulse" />
                            
                            {/* Multi-layered Radar Rings */}
                            <div className="absolute h-[120px] w-[120px] rounded-full border border-primary/10 animate-[ping_4s_cubic-bezier(0,0,0.2,1)_infinite]" />
                            <div className="absolute h-20 w-20 rounded-full border border-primary/30 border-dashed animate-[spin_10s_linear_infinite]" />
                            <div className="absolute h-14 w-14 rounded-full border-2 border-primary/50 animate-[spin_3s_linear_infinite_reverse] border-t-transparent border-b-transparent shadow-[0_0_15px_rgba(255,193,7,0.3)]" />
                            
                            {/* Tech Crosshairs */}
                            <div className="absolute h-12 w-[1px] bg-primary/40" />
                            <div className="absolute h-[1px] w-12 bg-primary/40" />

                            {/* Glowing Hexagon Core Container */}
                            <div 
                              className="absolute h-8 w-8 bg-primary/20 backdrop-blur-sm flex items-center justify-center border border-primary/50 shadow-[0_0_20px_rgba(255,193,7,0.4)]"
                              style={{ clipPath: 'polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%)' }}
                            >
                               <div className="h-full w-full bg-primary/10 animate-pulse" />
                            </div>
                            
                            {/* Bright Core Dot */}
                            <div className="relative h-3.5 w-3.5 rounded-full bg-[#FBC600] shadow-[0_0_30px_rgba(255,193,7,1),0_0_10px_rgba(255,255,255,0.8)] z-10" />
                          </>
                        ) : (
                          // Enhanced Branch Design
                          <>
                            {/* Responsive Aura */}
                            <div className="absolute inset-0 rounded-full blur-[10px] transition-all duration-300 bg-primary/30 scale-[5] group-hover:bg-primary/60 group-hover:scale-[7]" />
                            
                            {/* Outer Solid Ring */}
                            <div className="absolute h-6 w-6 rounded-full border border-primary/40 group-hover:border-primary group-hover:scale-110 transition-transform duration-300" />
                            
                            {/* Inner Dashed Rotating Ring */}
                            <div className="absolute h-4 w-4 rounded-full border border-primary/60 border-dashed animate-[spin_6s_linear_infinite] group-hover:animate-[spin_2s_linear_infinite]" />
                            
                            {/* Bright Core Dot */}
                            <div className="relative h-2 w-2 rounded-full bg-[#FBC600] shadow-[0_0_12px_rgba(255,193,7,0.9)] group-hover:bg-white group-hover:shadow-[0_0_15px_rgba(255,255,255,0.9)] transition-colors duration-300 z-10" />
                          </>
                        )}
                      </div>

                      {/* Enhanced Label */}
                      {!isActive && (
                        <div className={`absolute top-full left-1/2 -translate-x-1/2 pointer-events-none text-center transition-all duration-300 ${isHQ ? "mt-6" : "mt-3"}`}>
                          <span
                            className={`font-bold tracking-wider text-white drop-shadow-[0_4px_4px_rgba(0,0,0,0.9)] whitespace-nowrap ${isHQ ? "text-sm sm:text-base text-primary" : "text-[11px] sm:text-xs"}`}
                          >
                            {c.name}
                          </span>
                          {/* {isHQ && (
                            <div className="mt-1 flex items-center justify-center">
                              <div className="border border-primary/40 bg-[#0a0a0c]/80 px-2.5 py-1 rounded-sm backdrop-blur-md shadow-[0_0_15px_rgba(255,193,7,0.15)] flex items-center gap-1.5">
                                <span className="h-1.5 w-1.5 rounded-full bg-[#FBC600] animate-pulse shadow-[0_0_5px_rgba(255,193,7,1)]" />
                                <span className="text-[9px] text-primary font-mono uppercase tracking-[0.2em]">Central Operations</span>
                              </div>
                            </div>
                          )} */}
                        </div>
                      )}

                      {/* Premium Cyberpunk UI Card */}
                      <AnimatePresence>
                        {isActive && (
                          <motion.div
                            initial={{ opacity: 0, y: 15, scale: 0.95 }}
                            animate={{ opacity: 1, y: 0, scale: 1 }}
                            exit={{ opacity: 0, y: 10, scale: 0.95 }}
                            transition={{ duration: 0.2, ease: "easeOut" }}
                            className="absolute bottom-full left-1/2 -translate-x-1/2 mb-6 w-[280px] sm:w-[320px] z-50 cursor-default"
                            onClick={(e) => e.stopPropagation()}
                          >
                            <div className="bg-[#0a0a0c] backdrop-blur-xl rounded-lg p-5 shadow-[0_20px_50px_-10px_rgba(0,0,0,1)] border border-primary/40 relative overflow-hidden">
                              {/* Card Accent Grid */}
                              <div className="absolute inset-0 opacity-10 bg-[linear-gradient(to_right,#fff_1px,transparent_1px),linear-gradient(to_bottom,#fff_1px,transparent_1px)] bg-[size:10px_10px] pointer-events-none z-0" />
                              <div className="absolute top-0 right-0 w-24 h-24 bg-primary/20 blur-[30px] rounded-full z-0" />

                              <div className="flex items-start justify-between relative z-10 border-b border-white/10 pb-3">
                                <div>
                                  <h3 className="text-lg font-bold text-white tracking-wide flex items-center gap-2">
                                    {c.name}
                                    {c.status === "active" ? (
                                      <span className="relative flex h-2 w-2">
                                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                                        <span className="relative inline-flex rounded-full h-2 w-2 bg-green-500"></span>
                                      </span>
                                    ) : (
                                      <span className="h-2 w-2 rounded-full bg-yellow-500" />
                                    )}
                                  </h3>
                                  <p className="text-[10px] uppercase tracking-widest text-primary/80 font-mono mt-1">
                                    {isHQ ? "Central Operations" : "Regional Hub"} //{" "}
                                    {c.id.toUpperCase()}
                                  </p>
                                </div>
                              </div>

                              <div className="pt-3 space-y-2 relative z-10 font-mono text-[11px] text-white/80">
                                <div className="flex justify-between items-center">
                                  <span className="flex items-center gap-1.5">
                                    <ShieldCheck className="h-3.5 w-3.5 text-primary" /> Verified
                                    Garages
                                  </span>
                                  <span className="text-white font-bold">
                                    {isHQ ? "12" : Math.floor(c.y % 4) + 2} Active
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="flex items-center gap-1.5">
                                    <Clock className="h-3.5 w-3.5 text-primary" /> 24/7 Support
                                  </span>
                                  <span className="text-green-400 font-bold flex items-center gap-1">
                                    <span className="h-1.5 w-1.5 rounded-full bg-green-500 animate-pulse" />{" "}
                                    Online
                                  </span>
                                </div>
                                <div className="flex justify-between items-center">
                                  <span className="flex items-center gap-1.5">
                                    <Users className="h-3.5 w-3.5 text-primary" /> Inspection Team
                                  </span>
                                  <span className="text-green-400 font-bold">Deployed</span>
                                </div>
                                <div className="flex justify-between items-center border-t border-white/5 pt-2 mt-1">
                                  <span className="flex items-center gap-1.5 text-white/50">
                                    Avg Response Time
                                  </span>
                                  <span className="text-primary font-bold">{c.response}</span>
                                </div>
                              </div>

                              <div className="mt-4 relative z-10 flex gap-2">
                                <button className="flex-1 bg-yellow-400 hover:bg-yellow-500 text-black font-bold text-xs py-2 rounded shadow-[0_0_15px_rgba(255,193,7,0.3)] transition-colors uppercase tracking-wider">
                                  Initialize Service
                                </button>
                              </div>
                            </div>
                            {/* Connector Line */}
                            <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 w-px h-6 bg-primary/40" />
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </div>
                  );
                })}
              </div>
            </div>
          </div>
        </motion.div>
      </div>
    </section>
  );
}
